import Foundation

/// Trained data for the Crazy Alpaca reader (generated from screen recordings; see AlpacaReader).
/// centroids: 16 tile types × 768 floats (16×16 RGB samples / face colour), little-endian Float32.
/// templates: 16 types × 36 rows × 32 cols × RGB at quarter resolution (full tile: face, outline, base).
/// mask / icon: 36×32 — pixels that belong to the tile, and pixels where the types differ.
enum AlpacaData {
    static let types = 16
    static let names = ["ชีส", "นม", "ข้าวโพด", "เพชร", "ต้นอ่อน", "หมวก", "ถั่ว", "เสียบ", "ถุงมือ", "เค้ก", "ส้อมมีด", "สเต็ก", "ถุงเท้า", "แครอท", "สำลี", "ไหมพรม"]
    static let emoji = ["🧀", "🥛", "🌽", "💎", "🌱", "🧢", "🫛", "🍢", "🧤", "🍰", "🍴", "🥩", "🧦", "🥕", "☁️", "🧶"]
    static let centroids: [Float] = {
        let d = Data(base64Encoded: centroidsB64)!
        return d.withUnsafeBytes { Array($0.bindMemory(to: Float.self)) }
    }()
    static let templates: [Float] = [UInt8](Data(base64Encoded: templatesB64)!).map { Float($0) }
    static let mask: [Bool] = [UInt8](Data(base64Encoded: maskB64)!).map { $0 != 0 }
    static let icon: [Bool] = [UInt8](Data(base64Encoded: iconB64)!).map { $0 != 0 }

    private static let centroidsB64 = ""
    private static let templatesB64 = ""
    private static let maskB64 = ""
    private static let iconB64 = ""
}
